return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Dutch','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-06 00:52+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'nl_NL','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" opgeslagen.','"%1$s" created. %2$d template updated.'=>'"%1$s" gemaakt. %2$d sjabloon bijgewerkt.' . "\0" . '"%1$s" gemaakt. %2$d sjablonen bijgewerkt.','"%s" created.'=>'"%s" gemaakt.','"product" (replaces "article")'=>'"product" (vervangt "artikel")','%1$d chars — good length. %2$s'=>'%1$d tekens — goede lengte. %2$s','%1$d chars — may be truncated in SERPs (aim for 140–160). %2$s'=>'%1$d tekens — kan worden ingekort in SERP\'s (streef naar 140–160). %2$s','%1$d chars — too short (aim for 140–160). %2$s'=>'%1$d tekens — te kort (streef naar 140–160). %2$s','%1$d internal, %2$d external.'=>'%1$d intern, %2$d extern.','%1$d of %2$d image(s) missing alt text.'=>'%1$d van %2$d afbeeldingen missen alt-tekst.','%d chars — good length.'=>'%d tekens — goede lengte.','%d external link(s), no internal links. Add internal links to related content.'=>'%d externe link(en), geen interne links. Voeg interne links toe naar gerelateerde inhoud.','%d H1 tags found — a page should have exactly one H1.'=>'%d H1-tags gevonden — een pagina moet precies één H1 hebben.','%d image(s), all have alt text.'=>'%d afbeelding(en), allemaal met alt-tekst.','%d language not yet linked'=>'%d taal nog niet gekoppeld' . "\0" . '%d talen nog niet gekoppeld','%d link updated.'=>'%d link bijgewerkt.' . "\0" . '%d links bijgewerkt.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d locale-bestand kon niet automatisch worden verwijderd (DISALLOW_FILE_MODS is ingesteld). Verwijder het handmatig via je server of WP-CLI: wp language core uninstall <locale>.' . "\0" . '%d locale-bestanden konden niet automatisch worden verwijderd (DISALLOW_FILE_MODS is ingesteld). Verwijder ze handmatig via je server of WP-CLI: wp language core uninstall <locale>.','%d locale file removed.'=>'%d locale-bestand verwijderd.' . "\0" . '%d locale-bestanden verwijderd.','%d locale pack installed.'=>'%d locale-pakket geïnstalleerd.' . "\0" . '%d locale-pakketten geïnstalleerd.','%d navigation reference updated.'=>'%d navigatielink bijgewerkt.' . "\0" . '%d navigatielinks bijgewerkt.','%d part reference updated.'=>'%d onderdeelreferentie bijgewerkt.' . "\0" . '%d onderdeelreferenties bijgewerkt.','%d words — below recommended minimum of 300.'=>'%d woorden — onder de aanbevolen minimum van 300.','%d words — very thin content. Consider expanding to at least 300 words.'=>'%d woorden — zeer dunne inhoud. Overweeg uit te breiden tot minstens 300 woorden.','%d words.'=>'%d woorden.','%s Archive'=>'%s Archief','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s is actief en geeft al JSON-LD van Schema.org weer. Lingua Forge heeft de eigen schema-uitvoer uitgeschakeld om conflicterende grafieken te voorkomen. In tegenstelling tot Open Graph — waar LF og:locale toevoegt boven de uitvoer van een andere plugin — kan schema niet schoon worden aangevuld: dubbele of overlappende JSON-LD-grafieken veroorzaken validatiefouten. Schakel schema-uitvoer uit in de gedetecteerde plugin als je wilt dat LF gestructureerde gegevens afhandelt.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s is actief en genereert zijn eigen sitemap. Die sitemap is gescheiden van die van LF. Beide moeten worden ingediend bij Google Search Console: de SEO-plugin sitemap bevat je inhoud; de LF sitemap voegt de meertalige alternatieve links toe. De LF sitemap wordt automatisch aangekondigd in robots.txt.','(avg %.1f hits/block)'=>'(gemiddeld %.1f hits/blok)','(avg %.1f hits/entry)'=>'(gemiddeld %.1f hits/entry)','(disabled)'=>'uitgeschakeld','(no title) #%d'=>'(geen titel) #%d','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} had geen vervangbare links — opnieuw scannen om te onderzoeken)','.txt file(s) in the directory'=>'.txt-bestand(en) in de map','/ 100'=>'/ 100','1 H1 ✓ — no H2 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — geen H2-kopjes gevonden. Het toevoegen van H2\'s verbetert de structuur.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d gelokaliseerde sjabloon(s) uit het &#8220;%2$s&#8221; thema worden bewaard in de database, maar zijn momenteel inactief. Ze worden weer actief als je dat thema opnieuw activeert. Om je vertalingen over te zetten naar het nieuwe thema, regenerateer ze via <strong>Instellingen → Lingua Forge → Router → FSE-sjabloon</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> automatisch te repareren link(en)','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> link(s) die handmatige beoordeling vereisen','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> verouderd(e) pad(pad(en))','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> sjabloonprobleem(pen)','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Er bestaat een fysiek robots.txt-bestand op de site root. WordPress\'s virtuele robots.txt — en LF\'s Sitemap: filter — worden omzeild. De LF sitemap wordt niet aangekondigd aan zoekmachines.','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Accepteert alleen gecompileerde .mo-bestanden. Bestandsnaam moet het patroon {textdomain}-{locale}.mo volgen. Het uploaden van een bestand met dezelfde naam als een bestaand bestand zal het vervangen.','Action'=>'Actie','Actions'=>'Acties','active'=>'actief','Active Languages'=>'Actieve talen','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Actieve talen: voeg elke taal toe die je wilt ondersteunen. Elke taal krijgt een URL-prefix of subdomein en een hreflang-tag in de &lt;head&gt; van de pagina.','Active Provider'=>'Actieve provider','Add entry'=>'Item toevoegen','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Instructies toevoegen om de concepttekst te verbeteren — bv. korter maken, een conclusie toevoegen, een formelere toon gebruiken, een FAQ-blok opnemen…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Voeg instructies toe om de concept te verbeteren — bijvoorbeeld korter maken, een conclusie toevoegen, een formelere toon gebruiken…','Add new entry'=>'Nieuw item toevoegen','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Voeg één term per regel toe. Zowel de bronterm als de doelweergave zijn vereist. De taalcombinatie bepaalt op welke vertaalopdrachten de beperking van toepassing is.','Add Sitemap directive to robots.txt'=>'Voeg Sitemap-richtlijn toe aan robots.txt','Add the following line to your robots.txt manually:'=>'Voeg de volgende regel handmatig toe aan je robots.txt:','Add WooCommerce product tags to Open Graph output'=>'Voeg WooCommerce-producttags toe aan Open Graph-uitvoer','Adds a link to the home page so visitors can browse in their language.'=>'Voegt een link toe naar de startpagina zodat bezoekers in hun taal kunnen browsen.','Administrators only (manage_options)'=>'Alleen beheerders (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Na het wijzigen van de primaire taal, wis de permalinks (sectie hieronder) zodat de URL-routing wordt bijgewerkt.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Na het wijzigen van de URL-structuurinstellingen (padvoorvoegsel ↔ subdomein), bezoek altijd Instellingen → Permalinks en klik op Wijzigingen opslaan om de herschrijfregels te verversen.','AI analysis failed. Please try again.'=>'AI-analyse mislukt. Probeer het opnieuw.','AI Behaviour Preset'=>'AI Gedragsvoorinstelling','AI cache cleared. %d entry was removed.'=>'AI-cache geleegd. %d item(s) verwijderd.' . "\0" . 'AI-cache geleegd. %d items verwijderd.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'AI-cache: lijst met gecachte AI-antwoorden met hit-tellingen. Wis de hele cache of de invoer van een enkele post. Gebruik "Wissen" voordat je een vertaalwijziging test — gecachte resultaten worden teruggegeven, zelfs als je de AI-voorinstelling of het model wijzigt, totdat de cache-invoer wordt verwijderd.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'AI-functies zijn optioneel. Taalroutering, hreflang, de taalomschakelaar en het vertaalgroep-systeem werken allemaal zonder dat er een provider is geconfigureerd.','AI Limits & Security'=>'AI Limieten & Beveiliging','AI provider returned an empty response.'=>'AI-provider gaf een lege reactie.','AI Recommendations'=>'AI-aanbevelingen','AI returned an unexpected response format. Please try again.'=>'AI gaf een onverwacht antwoordformaat. Probeer het opnieuw.','AI Usage'=>'AI-gebruik','AI Usage & Cache'=>'AI-gebruik & cache','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Streef naar 120–160 tekens. Laat leeg om de fallback van het fragment te gebruiken.','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'Alle grote zoekmachines — Google, Bing en Yandex — ontdekken de sitemap automatisch via de Sitemap: richtlijn in robots.txt. Geen handmatige actie vereist. De knoppen hieronder sturen een directe ping zodat de zoekmachine de sitemap nu opnieuw crawlt in plaats van te wachten op de volgende geplande robots.txt-controle.','All time'=>'Alles','All types'=>'Alle types','Allow editors to lock individual blocks'=>'Sta redacteuren toe om individuele blokken te vergrendelen','Allow Gutenberg template-editing mode on post screens'=>'Sta Gutenberg sjabloonbewerkingsmodus toe op berichtenschermen','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Verwijder ook taaltoewijzingen, vertaalrelaties, meta-beschrijvingen, woordenlijst en Vertaalgeheugen wanneer de plugin wordt verwijderd.','Also generate meta description'=>'Ook meta beschrijving genereren','Alternative (server-side):'=>'Alternatief (serverzijde):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Altijd alleen og:locale en og:locale:alternate uitzenden. Gebruik wanneer een andere plugin of thema de volledige OG-set afhandelt.','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Altijd de volledige OG + Twitter Card set uitzenden, ongeacht andere plugins. Gebruik alleen als geen andere plugin OG-tags uitzendt.','An unknown error occurred.'=>'Er is een onbekende fout opgetreden.','Analysis'=>'Analyse','Analysis request failed. Please try again.'=>'Analyseren aanvraag mislukt. Probeer het opnieuw.','Analyze'=>'Analyseren','Analyzing…'=>'Bezig met analyseren…','and'=>'en','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'any','API calls saved by cache'=>'API-aanroepen opgeslagen door cache','API Key'=>'API-sleutel','API Keys'=>'API-sleutels','API Keys Tab'=>'API-sleutels tabblad','API Response Cache'=>'API-antwoordcache','Appends the following line to your existing robots.txt: %s'=>'Voegt de volgende regel toe aan je bestaande robots.txt: %s','Applied ✓'=>'Toegepast ✓','Apply failed — please try again.'=>'Toepassen mislukt — probeer het opnieuw.','Apply to Block'=>'Toepassen op blok','Apply to Editor'=>'Toepassen op Editor','Apply to Footnote'=>'Toepassen op voetnoot','Apply to Meta Description'=>'Toepassen op Meta Beschrijving','Apply translation'=>'Vertaling toepassen','Applying…'=>'Toepassen…','Approximate size'=>'Geschatte grootte','Archive'=>'Archief','Archive: %s'=>'Archief: %s','Article / WebPage'=>'Artikel / Webpagina','Article / WebPage — all singular posts and pages'=>'Artikel / Webpagina — alle enkelvoudige berichten en pagina\'s','Authors and above (edit_published_posts)'=>'Auteurs en hoger (edit_published_posts)','Auto (recommended)'=>'Auto (aanbevolen)','Behavior'=>'Gedrag','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Gedrag: kies de AI-voorinstelling (Letterlijk, Gebalanceerd, Creatief), voeg site-brede aangepaste prompt-instructies toe, schakel automatische post-opslag vertaling in of uit, en configureer het Vertaalgeheugen.','Block Content'=>'Blokinhoud','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Toont een beleefde kennisgeving wanneer de huidige pagina in de brontaal wordt weergegeven omdat er geen vertaling bestaat voor de taal van de bezoeker. Aangedreven door het LINGUAFORGE_LANG_FALLBACK_ACTIVE signaal van de Lingua Forge router — geeft niets af wanneer er een vertaling bestaat voor de gevraagde taal.','Block Editor'=>'Block Editor','block keywordfallback'=>'fallback','block keywordi18n'=>'i18n','block keywordlanguage'=>'taal','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'vertaling','Block locking'=>'Blokvergrendeling','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Patronen geregistreerd voor aangepaste berichttypen. Gebruik de Vertaal-knop om een taalvariant te produceren. De vertaalde inhoud wordt hier opgeslagen en kan worden gekopieerd naar elk CPT-bericht vanuit de blokeditor Pattern-inserter of gebruikt als uitgangspunt voor een Gesynchroniseerd patroon (Herbruikbaar blok).','block titleMissing Translation Notice'=>'Kennisgeving ontbrekende vertaling','Block translation reuses'=>'Blokvertaling hergebruik','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Blokniveau vertalingscache gedeeld tussen berichten. Wanneer ingeschakeld, worden identieke blokken (zelfde markup, taalcombinatie en woordenlijst) uit het geheugen gehaald in plaats van de AI opnieuw te bellen. Configureer in Instellingen → Gedrag.','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Blogberichten gebruiken Artikel; alle andere berichttypen en pagina\'s gebruiken WebPage. Bevat kop, beschrijving, inLanguage, url, datumPublicatie, datumWijziging, afbeelding en uitgever.','Browser language redirect'=>'Browsertaal omleiding','Built-in preset instructions:'=>'Ingebouwde preset-instructies:','Bulletize (•-prefixed)'=>'Opsommen (•-voorvoegsel)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Cache vertaalde equivalenten op blokniveau zodat herbruikbare inhoud (gedeelde voetteksten, zijbalken, accordions, juridische secties met veel boilerplate) niet elke keer een API-aanroep doen. Wanneer ingeschakeld, parseert de vertaalstroom elk bericht in blokken, zoekt elk blok op in de cache, en stuurt alleen niet-geladen blokken naar de AI in één batch-aanvraag. Wijzigingen in woordenlijst en nalevingspreset maken automatisch de getroffen cache-vertalingen ongeldig. Bekijk statistieken en wis de cache onder Onderhoud.','cached'=>'gecachet','Cached API responses'=>'Gecachte API-antwoorden','Cached block translations'=>'Gecachte blokvertalingen','Cancel'=>'Annuleren','Cannot determine target language from slug.'=>'Kan doeltaal niet bepalen uit slug.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Kan niet schrijven naar product %1$d: het is een vertaalde versie (taal: %2$s)%3$s. Operationele gegevens (prijs, voorraad, SKU, afmetingen) moeten worden bijgewerkt op het bronproduct. Los de bronproduct-ID op via: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'Canonical-tag','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Beperk hoeveel AI-gebruik de site kan genereren en beperk welke gebruikersrollen betaalde AI-aanroepen kunnen triggeren. Staat boven de per-gebruiker limiet (30 verzoeken / minuut, hardcoded) die al bescherming biedt tegen runaway loops van één gebruiker.','chars'=>'tekens','Chunk translated'=>'Gedeelte vertaald','Chunk translated to:'=>'Gedeelte vertaald naar:','Clear'=>'Wis','Clear All'=>'Alles wissen','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Alle gecachte AI-resultaten wissen? Toekomstige verzoeken zullen nieuwe API-aanroepen triggeren totdat de cache opnieuw is opgebouwd.','Clear API Response Cache'=>'Wis API-antwoordcache','Clear Debug Files'=>'Debug-bestanden wissen','Clear hints'=>'Hints wissen','Clear input'=>'Wis invoer','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Maak het hele Vertaalgeheugen leeg? Toekomstige vertalingen zullen de cache opnieuw opbouwen terwijl ze worden uitgevoerd.','Clear Translation Memory'=>'Vertaalgeheugen wissen','Close'=>'Sluiten','Close language panel'=>'Sluit taalpaneel','Close popover'=>'Sluit popover','Compatibility'=>'Compatibiliteit','Compliance Preset'=>'Nalevingspreset','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Configureer een AI-provider in Instellingen → API-sleutels om AI-aangedreven aanbevelingen mogelijk te maken.','Content generated'=>'Inhoud gegenereerd','Content Generator'=>'Content Generator','Content ready'=>'Inhoud klaar','Contributors and above — default (edit_posts)'=>'Bijdragers en hoger — standaard (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Beheer hoeveel inhoud naar de AI wordt gestuurd en hoe groot het antwoord mag zijn. Laat een veld leeg om de ingebouwde standaard te gebruiken (als placeholder weergegeven). Verhoog deze waarden als grote pagina\'s worden afgekapt; verlaag ze om API-kosten te verminderen.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Regelt het tokenbudget en de invoerlimieten voor de AI Content Generator-functie. Laat velden leeg om de ingebouwde standaardwaarden te gebruiken.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Regelt wat er gebeurt wanneer een beheerder de plugin verwijdert via Plugins → Geïnstalleerde plugins → Verwijderen. Plugin-instellingen en AI-caches worden altijd verwijderd. Taaltoewijzingen en vertaalrelaties worden standaard bewaard zodat een per ongeluk deïnstallatie of herinstallatie kan hervatten waar het was gebleven.','Conversational'=>'Conversatie','Copied ✓'=>'Gekopieerd ✓','Copy'=>'Kopiëren','Copy failed — please copy the URL manually.'=>'Kopiëren mislukt — kopieer de URL handmatig.','Copy markup'=>'Markup kopiëren','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Kopieer de huidige URL naar het klembord. Toont een "Link gekopieerd"-melding bij succes.','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Kopieer het resultaat en plak het waar nodig (bijvoorbeeld direct in het voetnootveld).','Copy to safe storage'=>'Kopieer naar veilige opslag','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'kopie/native/automatische JS-acties: afgehandeld door LF\'s social-share.js','Could not add entry: source term and target term are required.'=>'Kan item niet toevoegen: bronterm en doeltaal zijn verplicht.','Could not copy the file. Check that the uploads folder is writable.'=>'Kon het bestand niet kopiëren. Controleer of de uploads-map schrijfbaar is.','Could not instantiate the provider.'=>'Kon de provider niet initialiseren.','Could not save the file. Check that the uploads folder is writable.'=>'Kon het bestand niet opslaan. Controleer of de uploads-map schrijfbaar is.','Could not save the glossary entry.'=>'Kan het woordenlijstitem niet opslaan.','Could not write to robots.txt. Check file permissions.'=>'Kon niet schrijven naar robots.txt. Controleer de bestandsrechten.','CPT Block Patterns'=>'CPT-blokpatronen','Create'=>'Aanmaken','Create missing'=>'Maak ontbrekend aan','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Het maken van vertalingen voor berichttype "%s" vereist een actieve integratie. Zorg ervoor dat de benodigde integratie is geïnstalleerd en actief.','Creating…'=>'Bezig met maken…','Creative / Marketing'=>'Creatief / Marketing','Creative / Marketing instructions'=>'Creatieve / Marketing instructies','Current content (will be overwritten)'=>'Huidige inhoud (zal worden overschreven)','Current status'=>'Huidige status','Current title'=>'Huidige titel','Current: {current}'=>'Huidig: {current}','Currently emitting'=>'Momenteel wordt uitgezonden','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Momenteel geërfd van de %s-constante. Het selecteren van een waarde hier overschrijft deze.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Momenteel overgeslagen voor berichten die blok-opmerking attribuutplaatsaanduidingen gebruiken (wp:details samenvulvelden, enz.) — ze vallen terug op de bestaande enkele-aanvraag vertaalpad.','Currently:'=>'Momenteel:','Custom'=>'Aangepast','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Dagelijkse AI-quotum bereikt (%1$d verzoeken). Reset om %2$s UTC.','Daily request limit'=>'Dagelijkse verzoeklimiet','Danger Zone'=>'Gevaarlijke zone','Debug Files'=>'Foutopsporingsbestanden','Debug files cleared. %d file was removed.'=>'Foutopsporingsbestanden gewist. %d bestand is verwijderd.' . "\0" . 'Foutopsporingsbestanden gewist. %d bestanden zijn verwijderd.','Debug logging'=>'Foutopsporing','Debug logging disabled.'=>'Foutopsporing uitgeschakeld.','Debug logging enabled.'=>'Foutopsporing ingeschakeld.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Foutopsporing: schakel het foutopsporingslog in om AI-prompts en API-antwoorden vast te leggen in een lokaal bestand. Schakel uit na probleemoplossing — de foutopsporingsmodus schrijft een bestand bij elk AI-verzoek.','Default OG image'=>'Standaard OG-afbeelding','Delete'=>'Verwijderen','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Verwijder alle .txt-bestanden in de debugmap? De map zelf blijft bestaan zodat toekomstige debug-schrijfbeurten nog steeds correct worden opgeslagen.','Delete all files for this override (both .mo and .po)?'=>'Verwijder alle bestanden voor deze overschrijving (zowel .mo als .po)?','Delete content data on uninstall'=>'Verwijder inhoudsgegevens bij deïnstallatie','Delete this glossary entry?'=>'Wil je dit woordenlijstitem verwijderen?','Describe what to write — topic, key points, structure…'=>'Beschrijf wat je wilt schrijven — onderwerp, kernpunten, structuur…','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Detecteer actieve SEO-plugins (Yoast, Rank Math, etc.) tijdens het uitvoeren. Geef alleen og:locale + og:locale:alternate weer wanneer een andere plugin al de volledige OG-set uitzendt; geef de volledige set weer wanneer er geen wordt gedetecteerd.','Directory'=>'Map','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Uitschakelen tijdens promptafstemming of wanneer je wilt dat elk verzoek de AI-provider bereikt. Uitschakelen verwijdert geen gecachte items — opnieuw inschakelen herstelt ze. Het onmiddellijk verhogen van API-uitgaven op drukke sites wordt verwacht wanneer het is uitgeschakeld.','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Uitschakelen alleen voor headless sites of volledig aangepaste hreflang-implementaties. Wanneer uitgeschakeld, verwijdert LF niet langer de WordPress-kern canonical-tag en onderdrukt het niet langer de SEO-plugin hreflang-uitvoer.','Disabled'=>'Uitgeschakeld','Disabled (by setting)'=>'Uitgeschakeld (door instelling)','Disabled (mode setting)'=>'Uitgeschakeld (modusinstelling)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Uitgeschakeld omdat de lf-social-share mu-plugin deze functie al biedt.','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS is ingesteld.','Display'=>'Weergave','Displays the Lingua Forge language switcher.'=>'Toont de Lingua Forge-taalwisselaar.','Do not output any OG tags.'=>'Geen OG-tags weergeven.','Documentation'=>'Documentatie','Done'=>'Klaar','Done — {done} of {total} post(s) fixed.'=>'Klaar — {done} van {total} bericht(en) gerepareerd.','Down'=>'Omlaag','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Download en installeer een WordPress kern taalpakket rechtstreeks van WordPress.org. Zodra geïnstalleerd, wordt de locale beschikbaar voor URL-routering en de AI-vertalingsworkflow. De lijst met beschikbare talen wordt op aanvraag opgehaald — klik op de knop hieronder om deze te laden.','Dropdown direction'=>'Dropdownrichting','edit'=>'bewerken','Editors and above (edit_others_posts)'=>'Editors en hoger (edit_others_posts)','Enable API response caching'=>'Schakel API-antwoordcaching in','Enable block-level translation cache reuse across posts'=>'Schakel blokniveau vertaalcache-hergebruik over berichten in','Enable Social Share URL rewriting for Social Icons blocks'=>'Schakel URL-herziening voor Social Share in voor Social Icons-blokken','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Voer je API-sleutel in voor ten minste één AI-provider. Sleutels worden versleuteld opgeslagen met AES-256-GCM met een sitespecifiek geheim (LINGUAFORGE_SECRET). Deel geen database-exporten zonder eerst het geheim te roteren.','environment variable'=>'omgevingsvariabele','Error'=>'Fout','Expand'=>'Uitbreiden','Expected: {expected}'=>'Verwacht: {expected}','External share services'=>'Externe deelservices','Extra guidance — tone, style, constraints, target audience…'=>'Extra begeleiding — toon, stijl, beperkingen, doelgroep…','Extra guidance — tone, style, constraints…'=>'Extra begeleiding — toon, stijl, beperkingen…','Failed. Please try again.'=>'Mislukt. Probeer het opnieuw.','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'Fallback-afbeeldings-URL die wordt gebruikt wanneer een pagina geen uitgelichte afbeelding, site-logo of site-icoon heeft. Getoond in sociale previews voor archieven, de blogindex en elke enkelvoudige pagina zonder miniatuur.','Feature'=>'Functie','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Functies zijn gegroepeerd in twee niveaus. Voer de exacte modelidentificatie voor elk niveau en provider in. Laat een veld leeg om de ingebouwde standaard te gebruiken (weergegeven als placeholder). Alleen de modellen van de actieve provider worden tijdens runtime aangeroepen — configureer de anderen vooraf als je wilt wisselen.','File copied to safe storage successfully.'=>'Bestand succesvol gekopieerd naar veilige opslag.','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Bestandswijzigingen zijn uitgeschakeld (DISALLOW_FILE_MODS).','Files'=>'Bestanden','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Bestanden worden opgeslagen in de onderstaande map. Handig voor het diagnosticeren van vertaalproblemen — zet het uit zodra je hebt wat je nodig hebt zodat de bestanden niet ophopen. Je kunt dit ook forceren vanuit wp-config.php met `define( \'LINGUAFORGE_AI_DEBUG\', true );` wat deze schakelaar overschrijft.','Filter'=>'Filter','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Filter op taal en berichttype, blader door je inhoud en klik op Analyse op elk item om een SEO-controle uit te voeren op basis van regels — titelgrootte, meta-beschrijving, woordtelling, kopstructuur, afbeeldings-Alt-dekking en interne links.','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filter met linguaforge_debug_dir om debug-uitvoer naar een niet-openbare locatie te leiden.','Finding'=>'Vinden','Fix'=>'Fix','Fix All'=>'Alles repareren','Fix all links'=>'Repareer alle links','Fix all parts'=>'Repareer alle onderdelen','Fix Links'=>'Links corrigeren','Fix Nav'=>'Navigatie corrigeren','Fix Parts'=>'Onderdelen corrigeren','Fix Template'=>'Sjabloon repareren','Fixing {n} / {total}…'=>'Reparatie van {n} / {total}…','Fixing…'=>'Bezig met repareren…','Flush Permalink Rules'=>'Permalinkregels verversen','Flush Permalinks'=>'Permalinks verversen','Flush Sitemap Cache'=>'Sitemap-cache legen','Footnote Content'=>'Voetnootinhoud','footnote(s) translated — applied together with content.'=>'voetnoten vertaald — toegepast samen met inhoud.','Footnotes'=>'Voetnoten','Footnotes payload (advanced)'=>'Voetnoten payload (gevorderd)','Forbidden'=>'Verboden','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Geforceerd UIT door de LINGUAFORGE_AI_DEBUG-constante in wp-config.php. Verwijder die regel om deze schakelaar hier te regelen.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Geforceerd AAN door de LINGUAFORGE_AI_DEBUG-constante in wp-config.php. Verwijder die regel om deze schakelaar hier te regelen.','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Forceert dat de sitemap bij de volgende aanvraag wordt hergenereerd. Gebruik na bulk-import of handmatige bewerking van vertaalrelaties.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Gevonden {parts} over <strong>{total}</strong> van <strong>{scanned}</strong> gescande bericht(en) voor <strong>{lang}</strong>.','From'=>'Van','Front Page'=>'Voorpagina','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE-localisatie: schets, vertaal en herstel links in Full Site Editing-sjablonen en sjabloononderdelen rechtstreeks vanaf dit tabblad.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'FSE-sjablonen gezaaid vanuit het actieve thema. Maak ze aan en pas ze aan in de Site Editor.','Full'=>'Volledig','Full Article'=>'Volledig artikel','Full post'=>'Volledige bericht','General'=>'Algemeen','Generate'=>'Genereer','Generate Content'=>'Inhoud genereren','Generate content…'=>'Inhoud genereren…','Generate Excerpt'=>'Fragment genereren','Generate Meta Description'=>'Meta beschrijving genereren','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Genereer de meertalige sitemap op /lf-sitemap.xml','Generated Content'=>'Gegenereerde inhoud','Generated meta description'=>'Gegenereerde meta beschrijving','Generating…'=>'Aan het genereren…','Generation failed.'=>'Generatie mislukt.','Getting started'=>'Aan de slag','Global AI preset'=>'Globale AI-preset','Global default (%s)'=>'Standaard wereldwijd (%s)','Glossary'=>'Woordenlijst','Glossary entry added.'=>'Woordenlijstitem toegevoegd.','Glossary entry removed.'=>'Woordenlijstitem verwijderd.','Glossary Tab'=>'Woordenlijst tabblad','Google (Gemini)'=>'Google (Gemini)','Headings'=>'Koppen','Hide'=>'Verberg','Hints'=>'Hints','Home link text'=>'Tekst startpagina link','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Hoe het in de vertaling moet verschijnen. Typ dezelfde waarde als de bronterm om de AI te instrueren deze woord voor woord te behouden.','How to use'=>'Hoe te gebruiken','Hreflang'=>'Hreflang','Hreflang output'=>'Hreflang-uitvoer','Hreflang settings saved.'=>'Hreflang-instellingen opgeslagen.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Pictogram + label','Icon only'=>'Alleen pictogram','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Als dit is aangevinkt, wordt bij het verwijderen van de plugin alle taaltoewijzingen, vertaalrelaties, meta-beschrijvingen, paginapresets, het AI-woordenboek en Vertaalgeheugen permanent verwijderd voor elke bericht op deze site. Dit kan niet worden teruggedraaid. Laat het uitgevinkt tenzij je volledig meertalige ondersteuning van de site verwijdert.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Als je een algemene SEO-plugin hebt geïnstalleerd, toont dit paneel hoe LF zich aanpast om dubbele output te voorkomen. Het doel is botsing vermijden — niet samenwerking. LF biedt altijd de meertalige SEO-laag (hreflang, og:locale, inLanguage schema) die kennis vereist van LF\'s taalrouteringsconfiguratie om correct te produceren.','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Als je Yoast SEO, Rank Math, All in One SEO of SEOPress hebt geïnstalleerd, detecteert Lingua Forge ze en past zich aan om dubbele output te voorkomen. Voor hreflang neemt LF volledig over en onderdrukt de output van de plugin omdat die plugins geen correcte hreflang kunnen produceren voor een meertalige routeringsconfiguratie. Voor Open Graph voegt LF alleen og:locale en og:locale:alternate toe — de meertalige signalen die de plugin niet kan leveren — en laat de basis OG-set aan de plugin over. Voor Schema.org schakelt LF zijn eigen output volledig uit om conflicterende JSON-LD-grafieken te voorkomen.','Images'=>'Afbeeldingen','Improve writing'=>'Verbeter schrijven','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'Voeg in de blokeditor een Social Icons-blok toe. Voor elk pictogram open je de link-instellingen en voer je een van de "share:"-waarden hieronder in als URL. Op de frontend vervangt LF dit door de juiste deel-URL voor de huidige pagina.','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Bevat naam, beschrijving, inLanguage, url, afbeelding en een Aanbieding met prijs, prijsvaluta en beschikbaarheid. Prijs en beschikbaarheid komen van het bronproduct (gedeeld voorraadmodel).','Includes site name, url, and inLanguage.'=>'Bevat sitenaam, url en inLanguage.','Informative'=>'Informatief','Input tokens'=>'Invoertokens','Install'=>'Installeren','Install a Language'=>'Een taal installeren','Installed SEO plugins'=>'Geïnstalleerde SEO-plugins','Installing…'=>'Installeren…','instock / oos / pending from WC stock status'=>'in voorraad / niet op voorraad / in afwachting van WC-voorraadstatus','Instructions (optional)'=>'Instructies (optioneel)','Instructions / key points'=>'Instructies / kernpunten','Integration API'=>'Integratie API','Internal Link Fixer'=>'Interne link reparateur','Introduction only'=>'Alleen introductie','Invalid file reference.'=>'Ongeldige bestandsreferentie.','Invalid filename.'=>'Ongeldig bestandsnaam.','Invalid language code.'=>'Ongeldige taalcodering.','Invalid language.'=>'Ongeldige taal.','Invalid locale code.'=>'Ongeldige locale-code.','Invalid or primary language.'=>'Ongeldige of primaire taal.','Invalid post ID.'=>'Ongeldige bericht-ID.','Invalid post type.'=>'Ongeldig berichttype.','Invalid template part.'=>'Ongeldig sjabloononderdeel.','Invalid template type.'=>'Ongeldig sjabloontype.','JavaScript-powered actions'=>'JavaScript-gestuurde acties','Key points, ideas, or structure to build from…'=>'Belangrijke punten, ideeën of structuur om vanaf te bouwen…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Sleutels worden versleuteld met AES-256-CBC voordat ze in de WordPress-database worden opgeslagen. Het encryptiegeheim wordt afgeleid van je WordPress-authentificatiesalts (wp-config.php), zodat platte tekst-sleutels nooit de database raken.','Language'=>'Taal','Language %s installed successfully.'=>'Taal %s succesvol geïnstalleerd.','Language (optional)'=>'Taal (optioneel)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Taalinstallatie is uitgeschakeld op deze server (DISALLOW_FILE_MODS is ingesteld).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Taalinstallatie is uitgeschakeld op deze server. De constante DISALLOW_FILE_MODS is ingesteld in wp-config.php. Installeer taalpakketten handmatig via WP-CLI: wp language core install de_DE','Language label'=>'Taallabel','Language Overrides'=>'Taal Overrides','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Taaloverschrijvingen: beheer aangepaste .po/.mo-overschrijvingsbestanden voor de Lingua Forge UI-strings. Gebruik dit in plaats van het direct bewerken van plugin-bestanden — overschrijvingen blijven bestaan na updates.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Taalpakketinstallatie mislukt. De taal is mogelijk al geïnstalleerd, de locale-code is mogelijk onjuist, of je server blokkeert bestandschrijfbevoegdheden.','Language Setup'=>'Taalinstelling','Language Switcher'=>'Taalschakelaar','Language switcher'=>'Taalomschakelaar','Language uninstalled. %d post deleted.'=>'Taal gedeïnstalleerd. %d bericht verwijderd.' . "\0" . 'Taal gedeïnstalleerd. %d berichten verwijderd.','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Taal-specifieke kopieën van de sjabloononderdelen van het thema. Zodra ze zijn opgebouwd, worden sjablonen bijgewerkt om te verwijzen naar het taal-specifieke onderdeel.','Language:'=>'Taal:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Talen die momenteel bekend zijn bij de router (afgeleid van geïnstalleerde WordPress locale-pakketten plus de primaire taal). Installeer extra taalpakketten in het onderstaande gedeelte om meer talen beschikbaar te maken voor routering en vertaling.','Last 30 days'=>'Afgelopen 30 dagen','Last 7 days'=>'Afgelopen 7 dagen','Last generated: %s'=>'Laatst gegenereerd: %s','Lead paragraph (≤60 w)'=>'Inleidende alinea (≤60 woorden)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Laat een modelveld leeg om de ingebouwde standaard voor dat niveau te gebruiken. De placeholder toont welk model wordt gebruikt.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Laat leeg voor merknamen en taal-onafhankelijke termen die ongeacht de taal waarin we vertalen gehandhaafd moeten worden.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Laat leeg om deze invoer op alle doeltalen toe te passen — ideaal voor merknamen, afkortingen en termen die in elke vertaling woord voor woord behouden moeten blijven.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Laat leeg om de bestaande sleutel te behouden. Voer een nieuwe waarde in om deze te vervangen.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Laat leeg om de ingebouwde standaard te gebruiken. Het wissen van een opgeslagen overschrijving herstelt de standaard bij de volgende opslag.','Legacy lf-social-share mu-plugin'=>'Legacy lf-social-share mu-plugin','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Legacy lf-social-share mu-plugin gedetecteerd. LF stelt de basis OG-set uit naar de mu-plugin en geeft alleen og:locale + og:locale:alternate weer. Je kunt de mu-plugin deactiveren — LF\'s ingebouwde Social Share (SEO → Social Share-tab) en Open Graph dekken dezelfde functionaliteit.','Legal / Compliance'=>'Juridisch / Compliance','Legal / Compliance instructions'=>'Juridische / Nalevingsinstructies','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF voegt altijd og:locale en og:locale:alternate toe — de meertalige OG-signalen die geen algemene SEO-plugin correct kan produceren. Voor de basis OG-set (og:title, og:description, og:image) geeft LF deze weer wanneer er geen andere plugin aanwezig is. Wanneer een SEO-plugin is geïnstalleerd, slaat LF de basisset over om dubbele tags te voorkomen — niet omdat de plugin "beter" is, maar omdat duplicatie geen waarde oplevert.','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF genereert zijn eigen sitemap met xhtml:link-alternates voor alle vertaalgroepen. Wanneer een SEO-plugin is geïnstalleerd, genereert het een aparte sitemap — beide bestaan onafhankelijk van elkaar. Dien beide in bij Google Search Console: de sitemap van de SEO-plugin voor inhoudsontdekking, de LF-sitemap voor taalrelatie-signalen.','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF geeft hreflang-tags weer en heeft de WordPress-kern canonical-tag verwijderd op meertalige pagina\'s.','LF is suppressing hreflang output from: %s'=>'LF onderdrukt hreflang-uitvoer van: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF geeft nauwkeurige hreflang voor elke geconfigureerde taal, inclusief x-default. Algemene SEO-plugins hebben geen toegang tot je LF-routeringsconfiguratie en zouden hreflang genereren op basis van onjuiste URL-veronderstellingen. LF onderdrukt hun output via filter om botsingen te voorkomen.','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF geeft meertalige JSON-LD met inLanguage-aanduidingen die gekoppeld zijn aan de routeringsconfiguratie. Wanneer een SEO-plugin is geïnstalleerd, schakelt LF zijn eigen schema volledig uit: dubbele JSON-LD-grafieken veroorzaken validatiefouten en er is geen eenvoudige manier om een bestaande grafiek aan te vullen.','LF provides'=>'LF biedt','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LF verwijdert de canonical-tag van WordPress op meertalige pagina\'s omdat de router\'s taal-voorkeur rewrite-regels en de hreflang x-default de juiste canonieke signalen zijn voor een meertalige site. Dit voorkomt een dubbele canonieke tag als een SEO-plugin er ook een uitzendt. LF voegt geen eigen canonical toe — de taalroutering maakt elke URL al canoniek.','Light'=>'Licht','Light (default — fast and cost-effective)'=>'Licht (standaard — snel en kosteneffectief)','Light (fast and cost-effective — Haiku / Flash)'=>'Licht (snel en kosteneffectief — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Licht: gebruikt voor meta-beschrijvingen en samenvattinggeneratie — snel, lage kosten.','Limit results to pages in the given Lingua Forge language code.'=>'Beperk resultaten tot pagina\'s in de gegeven Lingua Forge-taalcode.','Limits'=>'Limieten','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge voegt meertalige routing, AI-gestuurde vertaling, hreflang SEO-tags en een taalomschakelaar toe aan je WordPress-site.','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge voegt WooCommerce-specifieke Open Graph-eigenschappen toe aan productpagina\'s zodat het delen van een product-URL op Facebook, Pinterest en soortgelijke platforms het juiste producttype, prijs en beschikbaarheid toont.','Lingua Forge AI Tools'=>'Lingua Forge AI-tools','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge breidt de WordPress Core Social Icons-blok uit met dynamische deel-URL\'s. Stel de link van een pictogram in op een "share:"-waarde en LF herschrijft deze naar de juiste deel-URL of JavaScript-actie bij het renderen — geen aangepaste code of third-party plugin nodig.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge genereert een speciale XML-sitemap op /lf-sitemap.xml die taal-variatielinks toevoegt voor al je vertaalde inhoud. Deze sitemap vult de WordPress-kern sitemap en elke SEO-plugin sitemap aan — vervangt ze niet.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge is een complete meertalige SEO-oplossing. Geen extra SEO-plugin nodig.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge is een complete meertalige SEO-oplossing. Geen extra SEO-plugin of sitemap-plugin nodig.','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge genereert <link rel="alternate" hreflang> tags voor elke geconfigureerde taal op elke pagina, inclusief x-default die naar de brontaal verwijst. Dit is het belangrijkste meertalige SEO-signaal voor Google en andere zoekmachines — er is geen extra SEO-plugin nodig.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge geeft Open Graph- en Twitter Card-meta-tags uit zodat gedeelde URL\'s de juiste taal, titel, beschrijving en afbeelding tonen op sociale platforms.','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge geeft Schema.org JSON-LD gestructureerde gegevens uit zodat zoekmachines je inhoudstype, taal en metadata begrijpen. Dit is de belangrijkste manier om inLanguage-aanduidingen voor meertalige inhoud te communiceren aan Google en andere crawlers.','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge beperkt standaard twee Gutenberg-functies om het redactionele gedrag consistent te houden over talen. Meld je hier aan als je volledige Gutenberg / FSE-mogelijkheden nodig hebt.','Lingua Forge Settings'=>'Lingua Forge-instellingen','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge gebruikt twee onafhankelijke cachelagen om overbodige AI API-aanroepen te voorkomen. Gebruik de tabbladen hieronder om elk te inspecteren en te beheren.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge gebruikt twee modelniveaus per provider:','Lingua Forge — Quick Translate'=>'Lingua Forge — Snelle Vertaling','Lingua Forge — Settings'=>'Lingua Forge — Instellingen','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'De ingebouwde Social Share- en Open Graph-modules van Lingua Forge dekken alle functionaliteit die de mu-plugin biedt, plus meertalige og:locale-ondersteuning. Je kunt de mu-plugin veilig deactiveren.','Link copied'=>'Link gekopieerd','link(s)'=>'link(en)','Links'=>'Links','Load available languages'=>'Beschikbare talen laden','Load content'=>'Inhoud laden','Loading…'=>'Laden…','Locale only'=>'Alleen locale','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Vergrendeld — een conflicterende SEO-plugin is actief. Zie de bovenstaande melding.','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate slaat zijn aangepaste vertalingen op in wp-content/languages/loco/ — een locatie die stilletjes kan worden gewist door een WP-kernupdate, plugin-herinstallatie, of als Loco Translate zelf wordt verwijderd. Bestanden hier kopiëren verplaatst ze naar de Lingua Forge i18n-overrides directory, die door al die gebeurtenissen blijft bestaan en automatisch wordt geladen bij elk verzoek.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Kopieer naar Veilige Opslag','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Laagste WordPress-capability die toegestaan is om AI-functies te activeren. Het aanscherpen hiervan op multi-auteur sites voorkomt dat bijdragers of proefaccounts betaalde AI-aanroepen uitvoeren. Overschrijf per functie via de linguaforge_required_capability filter.','Maintenance'=>'Onderhoud','Maintenance Tab'=>'Onderhoud tabblad','Make casual'=>'Informeler maken','Make concise'=>'Bondiger maken','Make formal'=>'Formeler maken','Mark citations needed'=>'Citaties markeren indien nodig','Max context characters'=>'Max context tekens','Max hints characters'=>'Max hints tekens','Max input characters'=>'Maximaal invoer tekens','Max output tokens'=>'Maximaal output tokens','Maximum characters accepted from the input field. Default: 8 000.'=>'Maximaal toegestane tekens uit het invoerveld. Standaard: 8.000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Maximaal aantal tekens van bestaande berichtinhoud dat wordt doorgegeven aan de AI als zaadcontext wanneer geen hints worden gegeven. Standaard: 6.000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Maximaal gelezen tekens uit het hints-veld. Standaard: 2.000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maximum aantal tekens van de berichtinhoud die naar de AI wordt doorgestuurd. 0 betekent geen limiet — de volledige inhoud wordt altijd verzonden (aanbevolen). Stel een niet-nul waarde in alleen als je provider een strakke contextvenster heeft. Er wordt een waarschuwing geschreven naar het PHP-foutlog wanneer de inhoud wordt ingekort.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Maximaal aantal tokens dat de AI in één vertaalantwoord mag produceren. Als een vertaling stilletjes wordt afgekapt, verhoog dan deze waarde. Standaard: 16.000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Maximaal tokens die de AI mag produceren per generatie. Verhoog dit als volledige artikelen worden afgekapt. Standaard: 8.192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Maximaal tokens die de AI mag produceren per snelle vertaling. Standaard: 2.000.','Meta Description'=>'Meta Beschrijving','Meta description'=>'Meta-beschrijving','Meta Description, Excerpt Generator'=>'Meta Beschrijving, Uittreksel Generator','Metric'=>'Metriek','Minimum role'=>'Minimale rol','Missing pattern name or language.'=>'Ontbrekende patroonnaam of taal.','Mode'=>'Modus','Model'=>'Model','Model tier'=>'Modelniveau','Models'=>'Modellen','Models Tab (General)'=>'Modellen tabblad (Algemeen)','Modified'=>'Gewijzigd','Most recent cached block'=>'Meest recente gecachte blok','Most recent cached response'=>'Meest recente gecachte antwoord','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Meertalige routing, SEO-meta-tags en AI-inhoudtools voor WordPress. Combineert taalherkenning, URL-routing, hreflang, metabeschrijvingen en AI-gestuurde fragmenten, meta\'s en vertaalfuncties.','Name displayed in this language. Leave empty to use the source name.'=>'Naam weergegeven in deze taal. Laat leeg om de bronnaam te gebruiken.','Navigation'=>'Navigatie','Navigation has no content to translate.'=>'Navigatie bevat geen inhoud om te vertalen.','Navigation not found.'=>'Navigatie niet gevonden.','Navigation posts are translated via the Router tab, not this button.'=>'Navigatieberichten worden vertaald via het Router-tabblad, niet via deze knop.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Navigatievertaling vereist een actieve AI-provider. Configureer een API-sleutel in het tabblad API-sleutels.','Navigations'=>'Navigaties','Network error — could not reach the WordPress AJAX endpoint.'=>'Netwerkfout — kon de WordPress AJAX-eindpunt niet bereiken.','No %s version found in this translation group.'=>'Geen %s-versie gevonden in deze vertalingsgroep.','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'Geen actie nodig. Google heeft in januari 2024 zijn sitemap-ping endpoint gedeprcieerd en ontdekt sitemaps nu uitsluitend via de robots.txt Sitemap: directive — die LF al heeft geconfigureerd. Google pikt het op bij de volgende crawl.','No AI provider configured.'=>'Geen AI-provider geconfigureerd.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Geen AI-provider geconfigureerd. Voeg een API-sleutel toe in Instellingen → API-sleutels.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Geen AI-gebruik geregistreerd in het geselecteerde venster (%s). Kies een breder bereik hierboven.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Nog geen AI-gebruik geregistreerd. Zodra een editor een vertaling uitvoert, een meta-beschrijving genereert of een andere AI-functie gebruikt, verschijnen de totalen hier.','No API key configured for this provider.'=>'Geen API-sleutel geconfigureerd voor deze provider.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Geen ingebouwde instructies — elke AI-functie gebruikt zijn eigen afgestemde standaardinstellingen. Vul het veld \'Aangepaste prompt-instructies\' hieronder in om je eigen site-brede regels toe te voegen.','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Geen conflicterende SEO-plugins gedetecteerd. Lingua Forge handelt alle SEO-uitvoer onafhankelijk af.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Nog geen aangepaste Loco Translate-bestanden gevonden. Ze verschijnen hier zodra je een vertaling opslaat in Loco Translate.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Geen externe OG-plugin gedetecteerd. LF geeft de volledige OG + Twitter Card set uit.','No file was selected.'=>'Geen bestand geselecteerd.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Geen woordenlijstitems die overeenkomen met het huidige filter. Wis het filter om alle items te zien, of voeg hieronder een nieuw item toe.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Nog geen woordenlijstitems. Voeg er hieronder een toe om terminologie in vertalingen af te dwingen.','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Geen H1 gevonden. Gewoonlijk is de posttitel de H1 — controleer of je thema deze uitzendt.','No images found in content.'=>'Geen afbeeldingen gevonden in de inhoud.','No internal links found to update.'=>'Geen interne links gevonden om bij te werken.','No language-specific template parts found to map.'=>'Geen taal-specifieke sjabloononderdelen gevonden om te koppelen.','No LF meta description set — using excerpt/content.'=>'Geen LF-meta-beschrijving ingesteld — gebruik excerpt/inhoud.','No links found. Internal links improve crawlability and user navigation.'=>'Geen links gevonden. Interne links verbeteren crawlbaarheid en gebruikersnavigatie.','No meta description found. Generate one via the AI meta description feature.'=>'Geen meta-beschrijving gevonden. Genereer er een via de AI-meta-beschrijvingsfunctie.','No navigation references needed updating.'=>'Geen navigatielinks die bijgewerkt hoeven te worden.','No override files uploaded yet.'=>'Nog geen overschrijvingsbestanden geüpload.','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Geen fysiek robots.txt-bestand gevonden. WordPress genereert het virtueel en LF\'s Sitemap-directive is automatisch inbegrepen.','No published posts found for the selected filters.'=>'Geen gepubliceerde berichten gevonden voor de geselecteerde filters.','No response from AI provider. Check your API key and try again.'=>'Geen reactie van AI-provider. Controleer je API-sleutel en probeer opnieuw.','No response from provider — check the error log for details.'=>'Geen reactie van de provider — controleer het foutlog voor details.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Geen secundaire talen geconfigureerd. Installeer een taalpakket hierboven om sjabloonopbouw mogelijk te maken.','No source content found to translate.'=>'Geen broninhoud gevonden om te vertalen.','No source page linked yet.'=>'Nog geen bronpagina gekoppeld.','No template part references needed updating.'=>'Geen sjabloononderdeelreferenties die bijgewerkt hoeven te worden.','No title set.'=>'Geen titel ingesteld.','No translated content found. The sitemap will populate once posts have been translated.'=>'Geen vertaalde inhoud gevonden. De sitemap wordt gevuld zodra berichten vertaald zijn.','No translation found — analyzed the source language version.'=>'Geen vertaling gevonden — geanalyseerd de bronversie.','No {lang} translation registered (TRID missing)'=>'Geen {lang} vertaling geregistreerd (TRID ontbreekt)','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Nog niet gegenereerd. De sitemap wordt gebouwd bij het eerste bezoek aan de sitemap-URL en gecached voor 24 uur.','Notes'=>'Notities','Nothing — all types disabled'=>'Niets — alle types uitgeschakeld','Notice message'=>'Kennisgevingsbericht','Notice settings'=>'Kennisgevingsinstellingen','Notify search engines'=>'Zoekmachines informeren','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'OG/Twitter Card-tags: afgehandeld door LF\'s Open Graph-module (SEO → Open Graph & Twitter Cards)','Oldest cached block'=>'Oudste gecachte blok','Oldest cached response'=>'Oudste gecachte antwoord','Only .mo files are accepted.'=>'Alleen .mo-bestanden worden geaccepteerd.','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'Open Graph &amp; Twitter Cards','Open Graph output'=>'Open Graph-uitvoer','Open Graph settings saved.'=>'Open Graph-instellingen opgeslagen.','Open Search Console →'=>'Open Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Open de native Web Share-sheet van de browser (iOS, Android, sommige desktops). Valt terug op kopiëren naar klembord als niet ondersteund.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Optioneel context voor editors (bijv. "ASIC = Application-Specific Integrated Circuit; in technische contexten in het Engels behouden").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Optioneel. Bing leest al de Sitemap: directive uit robots.txt — dit triggert een onmiddellijke hercrawl in plaats van te wachten op de volgende geplande controle.','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Optioneel. Yandex leest al de Sitemap: directive uit robots.txt — dit triggert een onmiddellijke hercrawl in plaats van te wachten op de volgende geplande controle.','Output'=>'Uitvoer','Output Article or WebPage schema on singular posts and pages'=>'Output Artikel- of WebPage-schema op enkelvoudige berichten en pagina\'s','Output hreflang tags in wp_head'=>'Output hreflang-tags in wp_head','Output mode'=>'Output-modus','Output Open Graph tags in wp_head'=>'Output Open Graph-tags in wp_head','Output Product schema on WooCommerce product pages'=>'Output Product-schema op WooCommerce-productpagina\'s','Output Schema.org JSON-LD in wp_head'=>'Output Schema.org JSON-LD in wp_head','Output tokens'=>'Uitvoertokens','Output WebSite schema on the front page and blog index'=>'Output WebSite schema op de voorpagina en blogindex','Overall SEO score'=>'Algemene SEO-score','overridden'=>'overschreven','Override file deleted.'=>'Overschrijvingsbestand verwijderd.','Override file uploaded successfully.'=>'Overschrijvingsbestand succesvol geüpload.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Overschrijft de AI-voorinstelling voor Vertaling en Inhoudsgeneratie op deze pagina. Alle andere functies gebruiken altijd de wereldwijde voorinstelling.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Overschrijft de AI-voorinstelling voor Vertaling en Inhoudsgeneratie op deze pagina. Site-brede aangepaste instructies (Instellingen → Gedrag) worden altijd toegevoegd aan elk verzoek, ongeacht deze selectie.','Overview'=>'Overzicht','Page'=>'Pagina','Part'=>'Onderdeel','Paste a footnote, sentence, or any snippet here…'=>'Plak hier een voetnoot, zin of fragment…','Paste text, or select text in the editor first…'=>'Plak tekst, of selecteer eerst tekst in de editor…','Paste text, or select text on the page first…'=>'Plak tekst, of selecteer eerst tekst op de pagina…','Paste your API key…'=>'Plak je API-sleutel…','Path prefix — example.com/de/'=>'Padvoorvoegsel — example.com/de/','Pattern'=>'Patroon','Pattern has no content to translate.'=>'Patroon heeft geen inhoud om te vertalen.','Pattern not found.'=>'Patroon niet gevonden.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Patroon vertaald en opgeslagen. Kopieer de inhoud naar je CPT-bericht via de blokeditor Pattern-inserter of gebruik het als startpunt voor een Herbruikbaar Blok.','Pattern translation failed.'=>'Patroonvertaling mislukt.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Per-bericht cache voor AI-gegenereerde vertalingen, meta-beschrijvingen, uittreksels en inhoud. Altijd actief — geen aparte schakelaar nodig. Items worden automatisch ongeldig gemaakt wanneer de inhoud of AI-leverancier/-model verandert.','Permalink rules flushed successfully.'=>'Permalink-regels succesvol gewist.','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Verwijdert permanent alle sjablonen, sjabloononderdelen, patronen, navigatiemenu\'s, berichten, pagina\'s, aangepaste berichttypen, producten en productvariaties die aan deze taal gekoppeld zijn. Verwijdert ook de WordPress-localebestanden zodat deze taal niet meer in de router verschijnt. Deze actie kan niet ongedaan gemaakt worden.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Verwijder %s permanent? Dit zal alle vertaalde inhoud voor deze taal verwijderen en kan niet ongedaan gemaakt worden.','Permission denied.'=>'Toestemming geweigerd.','Persuasive'=>'Overtuigend','PHP constant'=>'PHP-constante','Pin on Pinterest'=>'Pin op Pinterest','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Pin termen die niet vertaald mogen worden of altijd op een specifieke manier moeten worden weergegeven (bijv. merknamen, productnamen, afkortingen). Woordenlijstbeperkingen worden in elke AI-vertaling aangebracht voor alle functies: berichtvertaling, meta-beschrijving, samenvatting en FSE-sjabloonvertaling.','Ping Bing'=>'Ping Bing','Ping Yandex'=>'Ping Yandex','Plain language'=>'Eenvoudige taal','Please enter some instructions first…'=>'Voer eerst wat instructies in…','Please enter some text first…'=>'Voer eerst wat tekst in…','Plugin'=>'Plugin','Post'=>'Bericht','Post not found or not published.'=>'Bericht niet gevonden of niet gepubliceerd.','Post not found.'=>'Bericht niet gevonden.','Post on X / Twitter'=>'Bericht op X / Twitter','Post Types'=>'Berichttypen','Prefilled from excerpt. Edit to override.'=>'Vooraf ingevuld uit fragment. Bewerk om te overschrijven.','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Prijs en beschikbaarheid weerspiegelen altijd het product in de brontaal (gedeeld voorraadmodel). Tags worden alleen weergegeven wanneer LF\'s Open Graph-module is ingesteld op "Volledig" of "Auto" modus zonder conflicterende SEO-plugin.','Primary Language'=>'Primaire taal','Primary language'=>'Primaire taal','Primary language saved.'=>'Primaire taal opgeslagen.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Primaal taal: de taal waarin je bestaande inhoud is geschreven. Alle vertalingen worden uit deze taal geproduceerd; het wijzigen ervan verplaatst of verwijdert geen berichten.','Processing…'=>'Bezig…','Product'=>'Product','Product Open Graph'=>'Product Open Graph','Product — WooCommerce product pages'=>'Product — WooCommerce productpagina\'s','Provider'=>'Provider','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Provider gaf geen tekst terug. Controleer het WordPress-foutlog voor de gedetailleerde reden van de fout.','Quality'=>'Kwaliteit','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kwaliteit (standaard — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kwaliteit (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Kwaliteit: gebruikt voor berichtvertaling en inhoudsgeneratie — hogere kwaliteit, hogere kosten.','Quick Translate'=>'Snel vertalen','Quick Translation'=>'Snelle Vertaling','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Snelle Vertaling wordt gebruikt voor snippet/fragmentmodus — korte passages vertaald op aanvraag vanuit de werkbalk, editor of blokpopovers. Het gebruikt een aparte, lichtere configuratie dan de volledige pagina vertaling om reacties snel en kosteneffectief te houden.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Heractiveert Gutenberg\'s canLockBlocks. Handig voor redactionele sjablonen die voorkomen dat bijdragers bepaalde blokken verplaatsen of verwijderen.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Heractiveert supportsTemplateMode. Kern voor workflows met volledige site-bewerking waar op berichtniveau sjabloonoverschrijvingen opzettelijk zijn.','Re-generates and updates the cached result.'=>'Genereert en werkt de gecachte resultaat bij.','Re-scan'=>'Opnieuw scannen','Re-scanning…'=>'Opnieuw scannen…','Re-translate'=>'Hertaal opnieuw','Reading time'=>'Leestijd','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Verwijs bezoekers door naar hun voorkeurstaal op basis van de Accept-Language header van de browser','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Verdere verfijning — bijvoorbeeld "korter maken" of "gebruik een formele toon"…','Refine further:'=>'Verder verfijnen:','Refinement'=>'Vernieuwing','Refinement failed — please try again.'=>'Vernieuwing mislukt — probeer het opnieuw.','Refining…'=>'Aan het verfijnen…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Hernoopt WordPress herschrijfregels zodat URL-prefixen, taalspecifieke slugs en archiefherschrijvingen allemaal in sync zijn. Nodig na het wijzigen van de primaire taal of het toevoegen van nieuwe taalondersteuning.','Remove stored key'=>'Verwijder opgeslagen sleutel','Report an issue on GitHub'=>'Meld een probleem op GitHub','Request failed — please try again.'=>'Verzoek mislukt — probeer het opnieuw.','Request failed.'=>'Verzoek mislukt.','Request failed. Check your connection.'=>'Aanvraag mislukt. Controleer je verbinding.','Request failed. Please try again.'=>'Aanvraag mislukt. Probeer het opnieuw.','Requests'=>'Verzoeken','Reset'=>'Reset','Result will appear here…'=>'Resultaat verschijnt hier…','Retranslate'=>'Vertaal opnieuw','Retranslating…'=>'Hervertalen…','Review carefully — links and slugs not updated.'=>'Bekijk het zorgvuldig — links en slugs niet bijgewerkt.','Review translation before applying'=>'Vertaling beoordelen voordat je toepast','Revise'=>'Herschrijf','Revision'=>'Herziening','Revision Type'=>'Herzieningstype','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt bijgewerkt met Sitemap-richtlijn.','Router'=>'Router','Router Tab'=>'Router tabblad','Run AI Analysis'=>'Voer AI-analyse uit','Save Debug Setting'=>'Debug-instelling opslaan','Save Hreflang Settings'=>'Opslaan Hreflang-instellingen','Save Open Graph Settings'=>'Opslaan Open Graph-instellingen','Save Router Settings'=>'Routerinstellingen opslaan','Save Schema.org Settings'=>'Opslaan Schema.org-instellingen','Save Settings'=>'Instellingen opslaan','Save Sitemap Settings'=>'Opslaan Sitemap-instellingen','Save Social Share Settings'=>'Opslaan Sociale Deel-instellingen','Save the post to persist changes.'=>'Sla het bericht op om wijzigingen te behouden.','Save Uninstall Setting'=>'Instelling voor deïnstallatie opslaan','Save WooCommerce SEO Settings'=>'Opslaan WooCommerce SEO-instellingen','Saved to the meta description field when you apply.'=>'Opgeslagen in het veld voor meta beschrijving bij het toepassen.','Scan failed: '=>'Scan mislukt: ','Scan request failed. Please try again.'=>'Scanverzoek mislukt. Probeer het opnieuw.','Scanning posts for broken language links…'=>'Posts scannen op gebroken taallinks…','Schema output deferred.'=>'Schema-uitvoer uitgesteld.','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'Schema.org JSON-LD','Schema.org output'=>'Schema.org-uitvoer','Schema.org settings saved.'=>'Schema.org-instellingen opgeslagen.','Search'=>'Zoeken','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'Search Console is handig voor het monitoren van indexerings- en dekkingsfouten, maar is niet vereist voor ontdekking.','Search Results'=>'Zoekresultaten','Security check failed — file path is not permitted.'=>'Beveiligingscontrole mislukt — bestandslocatie is niet toegestaan.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Kies een taal om de FSE-sjablonen, sjabloononderdelen en navigatiemenu\'s te beheren.','Select language'=>'Selecteer taal','Send via Telegram'=>'Verstuur via Telegram','Send via WhatsApp'=>'Verstuur via WhatsApp','SEO'=>'SEO','SEO Analysis'=>'SEO-analyse','SEO character-count info'=>'SEO-tekenaantal info','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'SEO-plugin(s) gedetecteerd: %s. LF geeft alleen og:locale en og:locale:alternate weer; de gedetecteerde plugin behandelt de volledige OG-set.','SEO plugins and conflict avoidance:'=>'SEO-plugins en conflictoplossing:','SEO Tab'=>'SEO-tabblad','Server setup (subdomain)'=>'Serverinstelling (subdomein)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Stelt het standaard AI-gedrag in voor alle functies site-breed. Individuele berichten kunnen dit overschrijven voor Vertaling en Inhoudsgeneratie via de Lingua Forge meta box.','Settings'=>'Instellingen','Settings saved.'=>'Instellingen opgeslagen.','Share on Facebook'=>'Delen op Facebook','Share on LinkedIn'=>'Delen op LinkedIn','Share on Mastodon'=>'Delen op Mastodon','Share via email (mailto:)'=>'Delen via e-mail (mailto:)','Show home link'=>'Toon startpagina link','Shown when no translation exists for the visitor\'s language.'=>'Toont wanneer er geen vertaling bestaat voor de taal van de bezoeker.','Single'=>'Enkelvoudig','Single %s'=>'Enkelvoud %s','Single: %s'=>'Enkelvoud: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Site-brede plafond op AI-verzoeken per UTC-dag (telt zowel Toolbar-vertalingen als blokwijzigingen). Teller wordt gereset om middernacht UTC. Zet op 0 om de limiet uit te schakelen.','Sitemap'=>'Sitemap','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Sitemap-cache geleegd. Het wordt opnieuw gegenereerd bij het volgende bezoek aan de sitemap-URL.','Sitemap output'=>'Sitemap-uitvoer','Sitemap settings saved.'=>'Sitemap-instellingen opgeslagen.','Sitemap URL'=>'Sitemap-URL','Size'=>'Grootte','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Social Icons-blok delen: URL\'s: afgehandeld door LF\'s ingebouwde Social Share (SEO → Social Share)','Social Share'=>'Social Share','Social Share settings saved.'=>'Social Share-instellingen opgeslagen.','Some link fixes failed.'=>'Sommige linkreparaties zijn mislukt.','Some nav ref fixes failed.'=>'Sommige navigatieverwijzingen reparaties zijn mislukt.','Some part fixes failed.'=>'Sommige onderdeelreparaties zijn mislukt.','Some parts could not be created.'=>'Sommige onderdelen konden niet worden gemaakt.','Some templates could not be created.'=>'Sommige sjablonen konden niet worden gemaakt.','Some translations failed.'=>'Sommige vertalingen zijn mislukt.','source'=>'bron','Source file not found.'=>'Bronbestand niet gevonden.','Source lang'=>'Bron taal','Source language'=>'Bron taal','Source term'=>'Bronterm','Standard'=>'Standaard','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standaard gebruikt de eigen afgestelde temperatuur van elke functie: Vertaling T=0.2 (nauwkeurig), Snelle Vertaling T=0.4, Inhoudsgenerator T=0.6 (creatief). De andere presets passen een enkele vaste temperatuur toe op alle functies.','Status'=>'Status','Status / Actions'=>'Status / Acties','Storytelling'=>'Storytelling','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Strikte-preservatiemodus voor juridische, regelgevende, medische of technische inhoud. Wanneer ingeschakeld, gebruikt elke AI-functie een lage bemonsteringstemperatuur en voegt de onderstaand addendum toe aan de systeemprompt — terminologie, artikelnummers, eenheden, merknamen en regelgeving worden letterlijk behouden in plaats van te worden geparafraseerd.','Structured Outline'=>'Gestructureerde schets','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Subdomeinmodus vereist dat je webserver alle taal-subdomeinen (bijvoorbeeld de.voorbeeld.com) naar deze WordPress-installatie wijst. Na het overschakelen van modi, vernieuw de permalinkregels en wis alle caches. Als je start-URL www bevat (bijvoorbeeld www.voorbeeld.com), gebruik dan de lf_base_domain filter om het bare apex-domein in te stellen zodat subdomeinen correct worden opgebouwd.','Subdomain — de.example.com/'=>'Subdomein — de.voorbeeld.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'Dien deze URL samen met je hoofdsitemap in bij Google Search Console.','Submit to Reddit'=>'Dien in bij Reddit','Suggested meta description'=>'Voorgestelde meta-beschrijving','Suggested title'=>'Voorgestelde titel','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Ondersteunde providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Slechts één provider is actief tegelijk. Selecteer de actieve provider op het Algemene tabblad.','Suppressed: %s.'=>'Onderdrukt: %s.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, per functie','Tag'=>'Tag','Tags emitted'=>'Uitgezonden tags','Target lang'=>'Doeltaal','Target Language'=>'Doeltaal','Target language'=>'Doeltaal','Target term'=>'Doeltaal','Target: 140–160 chars for optimal SERP display'=>'Doel: 140–160 tekens voor optimale SERP-weergave','Technical'=>'Technisch','Technical / Scientific'=>'Technisch / Wetenschappelijk','Technical / Scientific instructions'=>'Technische / Wetenschappelijke instructies','Template "%s" already exists.'=>'"%s" bestaat al.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Sjabloon "{expected}" bestaat niet — maak het eerst in de Site Editor aan.','Template has no content.'=>'Sjabloon heeft geen inhoud.','Template mode'=>'Sjabloonmodus','Template not found or not stored in the database.'=>'Sjabloon niet gevonden of niet opgeslagen in de database.','Template part "%s" already exists.'=>'"%s" bestaat al.','Template part has no content.'=>'Sjabloononderdeel heeft geen inhoud.','Template part not found or not stored in the database.'=>'Sjabloononderdeel niet gevonden of niet opgeslagen in de database.','Template Parts'=>'Sjabloononderdelen','Templates'=>'Sjablonen','Test connection'=>'Testverbinding','Testing…'=>'Bezig met testen…','Text domain / locale'=>'Tekstdomein / regio','Text to translate'=>'Tekst om te vertalen','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'De API-antwoordcache slaat het ruwe resultaat van elk AI-verzoek op — vertaling, meta-beschrijving, samenvatting en inhoudsgeneratie — op basis van een hash van de invoer (inhoud, taalcombinatie, provider, model). Volgende verzoeken met identieke invoer worden uit de cache gehaald zonder API-aanroep. De cache verschilt van Vertaalgeheugen: Vertaalgeheugen werkt op blokniveau en wordt gedeeld tussen berichten; de API-antwoordcache werkt op functieniveau en is per bericht geordend.','The editor did not accept the content — please try again.'=>'De editor heeft de inhoud niet geaccepteerd — probeer het opnieuw.','The following directive is active in your virtual robots.txt:'=>'De volgende richtlijn is actief in je virtuele robots.txt:','The lf-social-share mu-plugin is active.'=>'De lf-social-share mu-plugin is actief.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'De lf-social-share mu-plugin is actief. Lingua Forge\'s ingebouwde Social Share is inactief — de mu-plugin regelt het herschrijven van share-URL\'s en de JS-acties.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'De Light-tier gebruikt het snelle model dat is geconfigureerd in de Models-tabel hierboven (standaard: Haiku / Flash). Schakel over naar Kwaliteit als je dezelfde vertaalkauwiteit nodig hebt als in de volledige pagina modus voor snippets.','The phrase as it appears in the source text.'=>'De uitdrukking zoals deze in de brontekst voorkomt.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'De primaire taal wordt altijd op de root van je site bediend — geen URL-prefix in padmodus, geen taal-subdomein in subdomeinmodus. Alle andere talen gebruiken of een /taal/ padprefix (bijvoorbeeld example.com/de/) of een taal-subdomein (bijvoorbeeld de.example.com), afhankelijk van de URL-structuur hieronder.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'Het tabblad SEO → Compatibiliteit toont de live detectiestatus en legt precies uit wat LF doet voor elk functiegedeelte.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'De share-URL weerspiegelt altijd de huidige pagina — geen handmatige URL-invoer nodig. De linguaforge_social_share_url filter laat je de opgeloste URL voor elke service overschrijven.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'De sitemap wordt automatisch aangekondigd in robots.txt. Alle grote zoekmachines — Google, Bing, Yandex — ontdekken het via robots.txt. Handmatige indiening is niet nodig.','The source page has no footnotes.'=>'De bronpagina heeft geen voetnoten.','The upload failed — please try again.'=>'De upload is mislukt — probeer het opnieuw.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'De WordPress-kern sitemap vermeldt alle URL\'s van je inhoud. De LF sitemap vertelt zoekmachines hoe taalversies zich tot elkaar verhouden via xhtml:link hreflang-varianten. Dien beide in bij Google Search Console voor volledige dekking.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Deze voetnoten komen van de bronpagina en worden hier alleen ter referentie weergegeven. Voeg ze toe aan deze pagina met de blokbewerker.','This is the source page. Footnotes are edited directly in the block editor.'=>'Dit is de bronpagina. Voetnoten worden direct in de blokbewerker bewerkt.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Deze sleutel wordt momenteel geleverd door een server %s en kan hier niet worden verwijderd. Voer een nieuwe sleutel hierboven in om deze te overschrijven met een databasewaarde.','This language is protected and cannot be uninstalled.'=>'Deze taal is beschermd en kan niet worden verwijderd.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Deze taal komt overeen met de locale van de WordPress-instantie en kan niet worden verwijderd.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: om een model terug te zetten naar de ingebouwde standaard, wis het veld en sla op.','Title'=>'Titel','Title is %d chars — aim for 50–60.'=>'Titel is %d tekens — streef naar 50–60.','Title is %d chars — may be truncated in SERPs (aim for 50–60).'=>'Titel is %d tekens — kan worden afgekapt in SERP\'s (streef naar 50–60).','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Om een aangepaste encryptiegeheim te gebruiken (in plaats van de afgeleide wp_salt-waarde), voeg dit toe aan wp-config.php:','Today'=>'Vandaag','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Tokenverbruik wordt samengevoegd per functie, provider en model. Vastgelegd bij elke succesvolle AI-aanroep; Testverbinding-pings worden uitgesloten zodat ze de totalen niet vertekenen.','Tone'=>'Toon','tone'=>'toon','Tone:'=>'Toon:','Too many AI requests. Please retry in %d seconds.'=>'Te veel AI-verzoeken. Probeer het opnieuw over %d seconden.','Total'=>'Totaal','Total tokens'=>'Totaal tokens','Translate'=>'Vertalen','Translate / Revise'=>'Vertalen / Herzien','Translate / Revise block'=>'Vertaal / Herzien blok','Translate all'=>'Vertaal alles','Translate chunk'=>'Chunk vertalen','Translate Content'=>'Inhoud vertalen','Translate missing'=>'Vertaling ontbreekt','Translate page…'=>'Pagina vertalen…','Translated content'=>'Vertaald inhoud','Translated Names'=>'Vertaald namen','Translated title'=>'Vertaald titel','Translated to:'=>'Vertaald naar:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Vertaald. Bekijk in de Site Editor — interne links, navigatie-URL\'s en sjabloon-slugs worden niet automatisch bijgewerkt.','Translating…'=>'Bezig met vertalen…','Translation'=>'Vertaling','Translation Caching'=>'Vertaalcache','Translation found but permalink could not be generated'=>'Vertaling gevonden, maar permalink kon niet worden gegenereerd','Translation Limits'=>'Vertaal Limieten','Translation Limits & Behavior'=>'Vertaallimieten & gedrag','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Vertaallimieten: bepaal welke gebruikersrollen AI-vertaling kunnen activeren, en stel een maandbudget in tokens in. Overschrijding van het budget onderbreekt AI-aanroepen totdat de maand is afgelopen.','Translation Memory'=>'Vertalingsgeheugen','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Vertaalgeheugen cachet AI-resultaten op basis van inhouds-hash, taalpaar, provider en model. Het bewerken van een bericht maakt de cache-invoer ongeldig, zodat de volgende vertaling een verse resultaat krijgt.','Translation Memory cleared. %d cached block was removed.'=>'Vertaalgeheugen gewist. %d gecachte blok is verwijderd.' . "\0" . 'Vertaalgeheugen gewist. %d gecachte blokken zijn verwijderd.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Vertaalgeheugen: slaat het volledige vertaalde bericht op per inhouds-hash. Wis het wanneer je een hervertaling van alle berichten wilt forceren, ongeacht of de inhoud is gewijzigd.','Translation workflow'=>'Vertaalworkflow','Translation, Content Generator'=>'Vertaling, Inhoudsgenerator','Type'=>'Type','Uli Hake'=>'Uli Hake','Uninstall %s'=>'Verwijder %s','Uninstall Behaviour'=>'Oninstallatiegedrag','Uninstall setting saved.'=>'Deïnstallatie-instelling opgeslagen.','unknown error'=>'onbekende fout','Unknown provider.'=>'Onbekende provider.','Unknown search engine.'=>'Onbekende zoekmachine.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'In tegenstelling tot hreflang — waar LF altijd andere plugins overschrijft omdat zij je meertalige configuratie niet kennen — is Open Graph anders: Yoast, Rank Math en soortgelijke plugins genereren al correcte OG-tags voor je inhoud. Ze dupliceren voegt geen waarde toe. In de automatische modus detecteert LF actieve SEO-plugins en voegt alleen toe wat zij niet kunnen bieden: og:locale (huidige taal) en og:locale:alternate (alle andere geconfigureerde talen).','Up'=>'Omhoog','Upload .mo file'=>'Upload .mo-bestand','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Upload gecompileerde .mo-bestanden om strings van derden plugin te overschrijven voor specifieke regio\'s — bijvoorbeeld een aangepaste VikBooking vertaling die "appartement" gebruikt in plaats van "kamer". Bestanden moeten voldoen aan de WordPress-naamgevingsconventie: {textdomain}-{locale}.mo (bijv. vikbooking-ca.mo). Ze worden opgeslagen in de uploads-map en blijven bestaan na plugin-updates.','Upload Override'=>'Upload Overschrijving','URL could not be mapped to a post — check the link target exists'=>'URL kon niet worden gekoppeld aan een bericht — controleer of de linkdoel bestaat','URL structure'=>'URL-structuur','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL-structuur: pad-prefix modus (example.com/de/) vereist geen serverwijzigingen. Subdomein modus (de.example.com) vereist een wildcard DNS-record, een wildcard SSL-certificaat, en een wijziging in de webserverconfiguratie — zie de Server Setup gids.','URL to enter'=>'URL om in te voeren','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Gebruik native delen wanneer beschikbaar; val terug op kopiëren naar klembord. Aanbevolen standaard voor "Delen" knoppen.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Gebruik de tabbladen bovenaan deze pagina om elk gebied te configureren. Wijzigingen in het Router-tabblad worden onmiddellijk doorgevoerd; wijzigingen in AI-sleutels en modelinstellingen gelden voor de volgende AI-aanvraag.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Gebruikersbeheer van terminologietabel per taalpaar. Items worden toegevoegd aan de vertaalprompt zodat de AI voorkeurstermen consequent gebruikt — essentieel voor domeinspecifieke vocabulaire ("kWp", "PPA", "interconnection point"), merknamen die niet vertaald mogen worden, en gestandaardiseerde regelgevingsteksten. Beide taalvelden zijn optioneel: laat "Bron taal" leeg om de invoer toe te passen ongeacht vanuit welke taal je vertaalt; laat "Doeltaal" leeg om het op alle doeltalen tegelijk toe te passen.','Using custom meta description.'=>'Gebruik van aangepaste meta beschrijving.','Using LF AI meta description.'=>'Gebruik van LF AI meta-beschrijving.','Value source'=>'Bron van waarde','View'=>'Bekijken','View built-in default'=>'Bekijk ingebouwde standaard','View current robots.txt'=>'Bekijk huidig robots.txt','View details'=>'Bekijk details','View Lingua Forge details'=>'Bekijk Lingua Forge-details','Visit plugin site'=>'Bezoek plugin-site','Warning:'=>'Waarschuwing:','WebSite'=>'WebSite','WebSite — front page / blog index'=>'WebSite — startpagina / blogindex','What LF provides — and collision avoidance'=>'Wat LF biedt — en botsingsvermijding','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Wat LF biedt: hreflang-tags voor elke geconfigureerde taal, Open Graph en Twitter Card-tags met og:locale en og:locale:alternate, Schema.org JSON-LD met inLanguage-annotaties, en een speciale meertalige sitemap op /lf-sitemap.xml met xhtml:link alternatieve vermeldingen voor alle vertaalgroepen.','When another SEO plugin is installed'=>'Wanneer een andere SEO-plugin is geïnstalleerd','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Wanneer foutopsporing is ingeschakeld (via de schakelaar hieronder of door LINGUAFORGE_AI_DEBUG te definiëren in wp-config.php), schrijven de vertaal- en FSE-sjabloonvertalingsfuncties hun ruwe AI-prompts en antwoorden naar schijf voor probleemoplossing. Gebruik deze sectie om die output te controleren en te wissen zodra je hebt wat je nodig hebt — de bestanden kunnen snel groeien op grote pagina\'s. Configureer de doelmap via de linguaforge_debug_dir filter.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Wanneer ingeschakeld, worden eerste keer bezoekers zonder taalcookie en zonder taalprefix in de URL doorgestuurd naar de dichtstbijzijnde overeenkomende taalversie. De omleiding wordt overgeslagen als de voorkeurstaal van de browser niet onder de actieve routertalen valt. Zodra een bezoeker een taal kiest via de switcher, krijgt de cookie prioriteit en wordt de browserheader genegeerd bij alle toekomstige bezoeken.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Wanneer ingeschakeld, geeft Lingua Forge de volgende extra meta-tags weer op productpagina\'s: og:type=product, og:price:amount, og:price:currency, og:availability, en hun product: namespace-equivalenten gebruikt door Facebook Catalog.','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Wanneer ingeschakeld, wordt de sitemap-URL automatisch aangekondigd in robots.txt en wordt de cache vernieuwd wanneer vertaalde inhoud wordt opgeslagen.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Wanneer Yoast SEO, Rank Math, All in One SEO of SEOPress actief is, onderdrukt Lingua Forge automatisch hun hreflang-uitvoer via filter. Algemene SEO-plugins genereren hreflang op basis van een URL-structuur voor één taal en kunnen niet rekening houden met je meertalige routingconfiguratie; de uitvoer van LF is altijd correct.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Welk modelniveau te gebruiken voor volledige pagina vertaling. Kwaliteit gebruikt het model dat in de Models tabel hierboven is geconfigureerd en wordt aanbevolen voor nauwkeurige, lange vertalingen. Schakel over naar Licht alleen als snelheid of kosten prioriteit heeft en de inhoud kort is.','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Tijdens activatie behandelt de mu-plugin de basis OG-sets en geeft LF alleen locale tags weer (auto-modus). Verwijdering schakelt LF automatisch over naar volledige OG-modus.','WooCommerce'=>'WooCommerce','WooCommerce product price'=>'WooCommerce productprijs','WooCommerce SEO settings saved.'=>'WooCommerce SEO-instellingen opgeslagen.','WooCommerce store currency'=>'WooCommerce winkelvaluta','Word count'=>'Woorden tellen','WP core canonical active (hreflang disabled)'=>'WP-kern canonical actief (hreflang uitgeschakeld)','WP-CLI reference'=>'WP-CLI referentie','Write AI prompts and responses to disk for troubleshooting'=>'Schrijf AI-prompts en antwoorden naar schijf voor probleemoplossing','XML Sitemap'=>'XML Sitemap','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Je kunt sleutels ook definiëren als constanten of omgevingsvariabelen (bijvoorbeeld in wp-config.php). Die bronnen worden automatisch gebruikt als fallback wanneer er geen database-sleutel is opgeslagen.','You do not have permission to manage these settings.'=>'Je hebt geen toestemming om deze instellingen te beheren.','You do not have permission to read this post.'=>'Je hebt geen toestemming om dit bericht te lezen.','{n} stale path(s)'=>'{n} verouderd(e) pad(pad(en))','~%d min read'=>'~%d min lezen' . "\0" . '~%d min lezen','— Any source language —'=>'— Elke bron taal —','— Any target language —'=>'— Elke doeltaal —','— Any target —'=>'— Elke doeltaal —','— Any —'=>'— Any —','— auto-detect —'=>'— automatisch detecteren —','— Deferred to plugin'=>'— Uitgesteld naar plugin','— Disabled'=>'— Uitgeschakeld','— Not detected'=>'— Niet gedetecteerd','— select a language —'=>'— kies een taal —','— toggle in Settings → Behavior.'=>'— schakel in Instellingen → Gedrag.','← Back'=>'← Terug','↑ Detected from current post'=>'↑ Gedetecteerd uit het huidige bericht','→ Locale tags only (manual setting)'=>'→ Alleen locale-tags (handmatige instelling)','→ Locale tags only — deferring base OG to plugin'=>'→ Alleen locale-tags — basis OG uitstellen tot plugin','↺ Re-translate'=>'↺ Hervertalen','↺ Refine'=>'↺ Verfijnen','↺ Refresh'=>'↺ Vernieuwen','↺ Refreshing…'=>'↺ Vernieuwen…','⚠ Borderline'=>'⚠ Randgeval','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Geen <strong>{lang}</strong> berichten gevonden. Zorg dat alle vertaalde berichten hun Taal-meta op <strong>{lang}</strong> hebben staan in de Taal-metabox.','⚠ No changes'=>'⚠ Geen wijzigingen','⚠ No changes — re-scan?'=>'⚠ Geen wijzigingen — opnieuw scannen?','✅ Fixed ({n})'=>'✅ Gerepareerd ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Geen gebroken links of sjabloonfouten gevonden voor <strong>{lang}</strong>. Gescand <strong>{scanned}</strong> bericht(en) en pagina(\'s) — alle controles geslaagd. Links naar sjabloononderdelen (header, footer, sidebar) zijn hier niet inbegrepen — gebruik de knop Fix Template Parts om die apart te controleren.','✅ Template fixed'=>'✅ Sjabloon gerepareerd','✓ %s notified successfully.'=>'✓ %s succesvol genotificeerd.','✓ Active'=>'✓ Actief','✓ Active at /lf-sitemap.xml'=>'✓ Actief op /lf-sitemap.xml','✓ Active — %d URL entry with language alternates'=>'✓ Actief — %d URL-vermelding met taalalternatieven' . "\0" . '✓ Actief — %d URL-vermeldingen met taalalternatieven','✓ Active — full OG + Twitter Cards'=>'✓ Actief — volledige OG + Twitter Cards','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Actief — alleen locale-tags (og:locale, og:locale:alternate)','✓ All parts created.'=>'✓ Alle onderdelen gemaakt.','✓ All templates created.'=>'✓ Alle sjablonen gemaakt.','✓ All translated.'=>'✓ Alles vertaald.','✓ Configured'=>'✓ Geconfigureerd','✓ Connection OK'=>'✓ Verbinding OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Inhoud gegenereerd — bekijk de overlay om te beoordelen, verfijnen en toepassen.','✓ Done'=>'✓ Gereed','✓ Enabled'=>'✓ Ingeschakeld','✓ Good length'=>'✓ Goede lengte','✓ Hreflang active'=>'✓ Hreflang actief','✓ In safe storage'=>'✓ In veilige opslag','✓ Language installed.'=>'✓ Taal geïnstalleerd.','✓ LF outputs'=>'✓ LF-uitvoeren','✓ LF outputs Article / WebPage / WebSite'=>'✓ LF voert Artikel / WebPage / WebSite uit','✓ LF outputs full OG + Twitter Cards'=>'✓ LF voert volledige OG + Twitter Cards uit','✓ LF outputs — plugin hreflang suppressed'=>'✓ LF-uitvoer — plugin hreflang onderdrukt','✓ Links fixed.'=>'✓ Links gerepareerd.','✓ Nav refs fixed.'=>'✓ Navigatieverwijzingen gerepareerd.','✓ Parts fixed.'=>'✓ Onderdelen gerepareerd.','✓ Pattern translated.'=>'✓ Patroon vertaald.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Fysiek robots.txt gevonden. LF\'s Sitemap-richtlijn is aanwezig.','✓ Refined — review the updated draft above.'=>'✓ Vernieuwd — bekijk de bijgewerkte versie hierboven.','✓ Translation saved'=>'✓ Vertaling opgeslagen','✓ WP core canonical removed'=>'✓ WP-kern canonical verwijderd','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ %s ping mislukt. De sitemap-URL wordt nog steeds aangekondigd in robots.txt — de zoekmachine ontdekt het bij de volgende crawl.','✗ Disabled'=>'✗ Uitgeschakeld','✗ Error:'=>'✗ Fout:','✗ Failed:'=>'✗ Mislukt:','✗ Not configured'=>'✗ Niet geconfigureerd','✗ Too long'=>'✗ Te lang','✗ Too short'=>'✗ Te kort','❌ Failed'=>'❌ Mislukt','📄 Wrong template'=>'📄 Verkeerd sjabloon','📍 Stale path (page moved)'=>'📍 Verouderd pad (pagina verplaatst)']];
